mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm, s.trade_status
  from mst_cust c join srm_supplier s on s.cust_id = c.cust_id
 where c.cust_cd = #{custCd}

mapper.sql:
 where p.pr_date between #{c.from} and #{c.to}
and p.status = #{c.status}
and p.plant_cd = #{c.plantCd}

   and (p.pr_no ilike #{c.keywordLike} escape '\' or p.reason ilike #{c.keywordLike} escape '\'
        or exists (select 1 from srm_pr_line l join mst_item i on i.item_id = l.item_id
                    where l.pr_id = p.pr_id and (i.item_cd ilike #{c.keywordLike} escape '\' or i.item_nm ilike #{c.keywordLike} escape '\')))
